<script setup lang="ts">
import { onMounted, ref } from 'vue'
import { apiRequest } from './api/client'
import { signOut } from './auth'
import { smartLedgerUrl, travelUrl } from './appLinks'
interface Policy {service:string;apiVersion:string;authentication:string;localDevelopment:boolean;maxRequestBytes:number;requestsPerMinute:number;writesPerMinute:number;rateLimitScope:string}
const policy=ref<Policy|null>(null),error=ref(''),loading=ref(false),planner=ref<{aiAvailable:boolean;aiRequestsPerDay:number;protocol?:string}|null>(null),geocoder=ref<{searchAvailable:boolean}|null>(null)
const apiAddress=import.meta.env.VITE_API_BASE_URL||'与门户同源'
const theme=(()=>{try{return localStorage.getItem('personal-portal-theme')||'system'}catch{return 'system'}})()
async function load(){loading.value=true;error.value='';try{policy.value=await apiRequest<Policy>('/api/v1/system/info')}catch(cause){error.value=cause instanceof Error?cause.message:'无法读取接口策略'}finally{const services=await Promise.allSettled([apiRequest<{aiAvailable:boolean;aiRequestsPerDay:number}>('/api/v1/planner/status'),apiRequest<{searchAvailable:boolean}>('/api/v1/maps/status')]);planner.value=services[0].status==='fulfilled'?services[0].value:null;geocoder.value=services[1].status==='fulfilled'?services[1].value:null;loading.value=false}}
onMounted(load)
</script>
<template><main class="api-management" :class="`portal-${theme}`"><header><a href="/">← 个人门户</a><button type="button" @click="signOut">退出账号</button></header><section><span class="api-eyebrow">SERVICE &amp; ACCESS</span><h1>API 管理</h1><p>查看当前账号可访问的服务、接口策略和错误追踪方式。</p><div class="api-service-grid"><article><h2>WhereToGo API</h2><dl><dt>接口地址</dt><dd>{{ apiAddress }}</dd><template v-if="policy"><dt>认证方式</dt><dd>{{ policy.authentication }}</dd><dt>运行模式</dt><dd>{{ policy.localDevelopment?'本机开发（仅回环访问）':'正式认证' }}</dd><dt>请求限额</dt><dd>每账号每分钟 {{ policy.requestsPerMinute }} 次，其中写入 {{ policy.writesPerMinute }} 次</dd><dt>请求大小</dt><dd>{{ (policy.maxRequestBytes/1024/1024).toFixed(0) }} MiB</dd><dt>接口版本</dt><dd>{{ policy.apiVersion }}</dd><dt>限流范围</dt><dd>当前服务实例</dd></template></dl><p v-if="error" role="alert" class="api-error">{{ error }}</p><div class="api-page-actions"><button type="button" :disabled="loading" @click="load">{{ loading?'读取中…':'刷新策略' }}</button><a :href="travelUrl">打开旅行规划 →</a></div></article><article><h2>SmartLedger API</h2><p>记账与门户共用统一账号，访问令牌和业务数据空间分别隔离。</p><p>在 SmartLedger 的“设置 → API 与安全”中查看对应服务的认证和限额。</p><a class="api-ledger-link" :href="smartLedgerUrl">打开 SmartLedger →</a></article></div><article class="api-trace"><h2>旅行规划服务</h2><dl><dt>收藏编排</dt><dd>{{ planner?'可使用 · 从已有收藏生成预览草稿':'暂未读取到状态' }}</dd><dt>外部 AI</dt><dd>{{ planner?.aiAvailable?'已配置 · 每账号每天最多 '+planner.aiRequestsPerDay+' 次（'+(planner.protocol||'chat-completions')+'）':'未配置 · 可继续使用收藏编排' }}</dd><dt>地点名称搜索</dt><dd>{{ geocoder?.searchAvailable?'已配置 · 点击查询后选择结果':'未配置 · 可使用地图选点或填写 WGS84 坐标' }}</dd></dl><p>AI 和搜索服务由部署者在后端配置。支持 Chat Completions（DeepSeek / GLM / GPT 兼容）、Responses 和 Claude Messages 三种协议。此处只显示配置状态，不返回服务密钥；已配置不等于供应商可用性已通过验证。</p><details><summary>如何配置本机 AI</summary><p>运行项目脚本 scripts/set-travel-ai.ps1，选择供应商、模型和接口协议，密钥通过隐藏输入填写，以 Windows DPAPI 加密保存到 D 盘应用目录。然后重启旅游 API。正式部署使用后端秘密环境变量，不能把密钥放入 VITE_ 设置。</p></details><a :href="travelUrl">打开旅行空间 →</a></article><article class="api-trace"><h2>接口错误与请求编号</h2><p>接口统一返回状态码、错误代码、说明与请求编号。遇到问题时，可使用页面提示中的请求编号定位服务日志。</p><div class="api-codes"><span><b>401</b> 登录过期</span><span><b>403</b> 无访问权限</span><span><b>409</b> 数据或版本冲突</span><span><b>413</b> 内容过大</span><span><b>429</b> 请求过于频繁</span></div></article></section></main></template>
