-scheme:dark){.api-management.portal-system{background:#111b29;color:#e3ebf6}.api-management.portal-system article,.api-management.portal-system button{background:#1b2635;border-color:#2c3b4e;color:#e3ebf6}.api-management.portal-system p,.api-management.portal-system dt,.api-management.portal-system .api-codes{color:#9caec4}.api-management.portal-system a,.api-management.portal-system .api-codes b{color:#9dc5f0}}</style>
